package main

const easyjsonJwriterPkg = "github.com/mailru/easyjson/jwriter"
const easyjsonJlexerPkg = "github.com/mailru/easyjson/jlexer"

// genCompat emits standard-library (and optionally easyjson) codec method
// wrappers so existing call sites use zerojson transparently. These
// replace the type's existing MarshalJSON/UnmarshalJSON, so the type must
// no longer be generated by easyjson.
func (g *generator) genCompat(ti typeInfo) {
	n := ti.name
	g.p("")
	// Value receiver so json.Marshal routes through zerojson for
	// non-addressable values too (a *T Marshaler is skipped for top-level
	// value and map-value marshals). UnmarshalJSON stays a pointer receiver.
	g.p("// MarshalJSON implements json.Marshaler via zerojson.")
	g.p("func (v %s) MarshalJSON() ([]byte, error) { return v.AppendZJSON(nil) }", n)
	g.p("")
	g.p("// UnmarshalJSON implements json.Unmarshaler via zerojson.")
	g.p("func (v *%s) UnmarshalJSON(data []byte) error { return v.UnmarshalZJSON(data) }", n)

	if g.compatEasyjson {
		writer := g.importAlias(easyjsonJwriterPkg, "jwriter")
		lexer := g.importAlias(easyjsonJlexerPkg, "jlexer")
		g.p("")
		g.p("// MarshalEasyJSON implements easyjson.Marshaler via zerojson.")
		g.p("func (v %s) MarshalEasyJSON(w *%s.Writer) {", n, writer)
		g.p("\tb, err := v.AppendZJSON(nil)")
		g.p("\tif err != nil { w.Error = err; return }")
		g.p("\tw.Raw(b, nil)")
		g.p("}")
		g.p("")
		g.p("// UnmarshalEasyJSON implements easyjson.Unmarshaler via zerojson.")
		g.p("// l.Raw() captures just this value's byte span (recursively, so a")
		g.p("// nested object/array is captured whole) and hands it to")
		g.p("// UnmarshalZJSON. l.Consumed() is guarded by IsStart() so it rejects")
		g.p("// trailing content in the outer document only when this call is the")
		g.p("// genuine top-level entry point (easyjson.Unmarshal), not when the")
		g.p("// method runs recursively as an ordinary field decode.")
		g.p("func (v *%s) UnmarshalEasyJSON(l *%s.Lexer) {", n, lexer)
		g.p("\tisTopLevel := l.IsStart()")
		g.p("\tif data := l.Raw(); l.Ok() {")
		g.p("\t\tif err := v.UnmarshalZJSON(data); err != nil { l.AddError(err) }")
		g.p("\t}")
		g.p("\tif isTopLevel {")
		g.p("\t\tl.Consumed()")
		g.p("\t}")
		g.p("}")
	}
}
